#!/bin/sh

# Build GaGa.app, a menu bar application bundle.
#
# Usage: ./build.sh [--install]
# --install copies the result to /Applications.

set -e
cd "$(dirname "$0")"

NAME="GaGa"
VERSION="${GAGA_VERSION:-2026.11.14}"
BUNDLE_ID="com.github.thekingziga.gaga"
APP="build/$NAME.app"

swift build -c release --arch arm64 --arch x86_64

rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"

cp ".build/apple/Products/Release/$NAME" "$APP/Contents/MacOS/$NAME"

# the icon is generated by Icon/make-icon.swift and committed; rebuild it
# with: swift Icon/make-icon.swift
cp "Icon/AppIcon.icns" "$APP/Contents/Resources/AppIcon.icns"

cat > "$APP/Contents/Info.plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleName</key>            <string>$NAME</string>
    <key>CFBundleDisplayName</key>     <string>$NAME</string>
    <key>CFBundleExecutable</key>      <string>$NAME</string>
    <key>CFBundleIdentifier</key>      <string>$BUNDLE_ID</string>
    <key>CFBundlePackageType</key>     <string>APPL</string>
    <key>CFBundleShortVersionString</key> <string>$VERSION</string>
    <key>CFBundleVersion</key>         <string>$VERSION</string>
    <key>LSMinimumSystemVersion</key>  <string>13.0</string>
    <key>NSHighResolutionCapable</key> <true/>
    <key>CFBundleIconFile</key>        <string>AppIcon</string>
    <key>CFBundleIconName</key>        <string>AppIcon</string>

    <!-- radio streams are routinely served over plain HTTP, and the
         streams file is the user's own list, so allow non-TLS loads
         for both the playlist fetch and the audio itself -->
    <key>NSAppTransportSecurity</key>
    <dict>
        <key>NSAllowsArbitraryLoads</key> <true/>
    </dict>
</dict>
</plist>
PLIST

# ad-hoc signature, so that the bundle keeps a stable identity across
# rebuilds (the system ties Now Playing and media keys to it):
codesign --force --sign - "$APP" >/dev/null 2>&1

echo "Built $APP"

if [ "$1" = "--install" ]; then
    rm -rf "/Applications/$NAME.app"
    cp -R "$APP" "/Applications/$NAME.app"
    echo "Installed /Applications/$NAME.app"
fi
